import json
import os
import shlex
import sys
from contextlib import contextmanager
from typing import IO, Any, Dict, Iterator, List, Optional, Protocol

if sys.platform == "win32":
    from subprocess import Popen

try:
    import click
except ImportError:
    sys.stderr.write(
        "It seems python-dotenv is not installed with cli option. \n"
        'Run pip install "python-dotenv[cli]" to fix this.'
    )
    sys.exit(1)

from .main import dotenv_values, set_key, unset_key
from .version import __version__


class _EnvironmentManager(Protocol):
    def set_key(
        self,
        dotenv_path: str,
        key: str,
        value: str,
        quote: str = "always",
        export: bool = False,
    ) -> tuple:
        ...

    def unset_key(self, dotenv_path: str, key: str, quote: str = "always") -> tuple:
        ...

    def dotenv_values(self, dotenv_path: Optional[str] = None, stream: Optional[IO[str]] = None) -> Dict[str, Optional[str]]:
        ...


def _default_manager() -> _EnvironmentManager:
    class DefaultManager:
        def set_key(
            self,
            dotenv_path: str,
            key: str,
            value: str,
            quote: str = "always",
            export: bool = False,
        ) -> tuple:
            return set_key(dotenv_path, key, value, quote, export)

        def unset_key(self, dotenv_path: str, key: str, quote: str = "always") -> tuple:
            return unset_key(dotenv_path, key, quote)

        def dotenv_values(self, dotenv_path: Optional[str] = None, stream: Optional[IO[str]] = None) -> Dict[str, Optional[str]]:
            return dotenv_values(dotenv_path, stream)

    return DefaultManager()
